begin;
with j as (select * from jsonb_to_recordset($law7d0004$[{"code_id":"APK_RF","article_number":"149","version_date":"2002-07-24","article_text":"1. В случае оставления искового заявления без рассмотрения производство по делу заканчивается вынесением определения.\n\nВ определении арбитражный суд указывает основания для оставления искового заявления без рассмотрения, а также решает вопрос о возврате государственной пошлины из федерального бюджета в случае, предусмотренном частью 2 статьи 148 настоящего Кодекса. (В редакции Федерального закона от 30.12.2021 № 440-ФЗ)\n\nКопии определения направляются лицам, участвующим в деле.\n\n2. Определение арбитражного суда об оставлении искового заявления без рассмотрения может быть обжаловано.\n\n3. Оставление искового заявления без рассмотрения не лишает истца права вновь обратиться в арбитражный суд с заявлением в общем порядке после устранения обстоятельств, послуживших основанием для оставления заявления без рассмотрения.","article_title":"Статья 149. Порядок и последствия оставления искового заявления без рассмотрения","amendment_eo_number":"95-ФЗ","amendment_date":"2002-07-24","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"646b16b49394410f8fc2c9b69e860430370303abaae95c15010b231e82fab2ea"},{"code_id":"APK_RF","article_number":"15","version_date":"2002-07-24","article_text":"1. Арбитражный суд принимает судебные акты в форме судебного приказа, решения, постановления, определения.\n\n2. Судебный акт, вынесенный арбитражным судом первой инстанции в порядке приказного производства, именуется судебным приказом.\n\nСудебный акт, принятый арбитражным судом первой инстанции при рассмотрении дела по существу, именуется решением.\n\n3. Судебные акты, принимаемые арбитражными судами апелляционной инстанции и судами кассационной инстанции, образованными в соответствии с Федеральным конституционным законом от 28 апреля 1995 года № 1-ФКЗ \"Об арбитражных судах в Российской Федерации\", по результатам рассмотрения апелляционных и кассационных жалоб, именуются постановлениями. Судебные акты, выносимые Верховным Судом Российской Федерации по результатам рассмотрения кассационных жалобы, представления в порядке, установленном статьями 2911 - 29115 настоящего Кодекса, именуются определениями. Судебные акты, принимаемые Президиумом Верховного Суда Российской Федерации по результатам рассмотрения надзорных жалобы, представления в порядке, установленном статьями 3081 - 30813 настоящего Кодекса, именуются постановлениями.\n\nВсе иные судебные акты арбитражных судов, принимаемые в ходе осуществления судопроизводства, именуются определениями.\n\n4. Принимаемые арбитражным судом судебные приказы, решения, постановления, определения должны быть законными, обоснованными и мотивированными.\n\n5. Судебный акт, за исключением акта, содержащего сведения, составляющие государственную или иную охраняемую законом тайну, если дело рассмотрено в закрытом судебном заседании, может быть выполнен в форме электронного документа, который подписывается судьей усиленной квалифицированной электронной подписью. В случае, если судебный акт принят судом коллегиально, он подписывается всеми судьями, рассматривавшими дело, усиленной квалифицированной электронной подписью.\n\nПри выполнении судебного акта в форме электронного документа дополнительно выполняется экземпляр данного судебного акта на бумажном носителе.\n\n(Дополнение частью - Федеральный закон от 23.06.2016 № 220-ФЗ)\n\n(Статья в редакции Федерального закона от 02.03.2016 № 47-ФЗ)","article_title":"Статья 15. Судебные акты арбитражного суда, Верховного Суда Российской Федерации","amendment_eo_number":"95-ФЗ","amendment_date":"2002-07-24","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"1ba77100a4b229b23d738d5fcb63ae1ac98b29ee5fd5229645a1622a5f3b783c"},{"code_id":"APK_RF","article_number":"150","version_date":"2002-07-24","article_text":"1. Арбитражный суд прекращает производство по делу, если установит, что:\n\n1) имеются основания, предусмотренные пунктом 1 части 1 статьи 1271 настоящего Кодекса; (В редакции Федерального закона от 28.11.2018 № 451-ФЗ)\n\n2) имеется вступивший в законную силу принятый по спору между теми же лицами, о том же предмете и по тем же основаниям судебный акт арбитражного суда, суда общей юрисдикции или компетентного суда иностранного государства, за исключением случаев, если арбитражный суд отказал в признании и приведении в исполнение решения иностранного суда;\n\n3) имеется принятое по спору между теми же лицами, о том же предмете и по тем же основаниям решение третейского суда, за исключением случаев, если арбитражный суд отказал в выдаче исполнительного листа на принудительное исполнение решения третейского суда либо если арбитражный суд отменил указанное решение; (В редакции Федерального закона от 29.12.2015 № 409-ФЗ)\n\n4) истец отказался от иска и отказ принят арбитражным судом;\n\n5) организация, являющаяся стороной в деле, ликвидирована;\n\n6) после смерти гражданина, являющегося стороной в деле, спорное правоотношение не допускает правопреемства;\n\n7) имеются основания, предусмотренные частью 7 статьи 194 настоящего Кодекса.","article_title":"Статья 150. Основания для прекращения производства по делу","amendment_eo_number":"95-ФЗ","amendment_date":"2002-07-24","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"e0f63471fb90c31a726410e40ef5a078bd0fc54f76dbf4ef9de4ecf665b30ccf"},{"code_id":"APK_RF","article_number":"151","version_date":"2002-07-24","article_text":"1. О прекращении производства по делу арбитражный суд выносит определение.\n\nВ определении арбитражный суд указывает основания для прекращения производства по делу, а также разрешает вопросы о возврате государственной пошлины из федерального бюджета в случае, предусмотренном частью 1 статьи 150 настоящего Кодекса, и распределении между сторонами судебных расходов. (В редакции Федерального закона от 30.12.2021 № 440-ФЗ)\n\nКопии определения направляются лицам, участвующим в деле.\n\n2. Определение арбитражного суда о прекращении производства по делу может быть обжаловано.","article_title":"Статья 151. Порядок и последствия прекращения производства по делу","amendment_eo_number":"95-ФЗ","amendment_date":"2002-07-24","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"003bf58415329e24ddf14b81f4f958a7fce9ef29df6691c9d74f777f92f3c9e5"},{"code_id":"APK_RF","article_number":"152","version_date":"2002-07-24","article_text":"Дело по спору о сносе самовольной постройки или ее приведении в соответствие с предельными параметрами разрешенного строительства, реконструкции объектов капитального строительства, установленными правилами землепользования и застройки, документацией по планировке территории, или обязательными требованиями к параметрам объектов капитального строительства, установленными федеральными законами, об изъятии земельного участка из земель сельскохозяйственного назначения должно быть рассмотрено арбитражным судом первой инстанции в срок, не превышающий одного месяца со дня поступления заявления в арбитражный суд, включая срок на подготовку дела к судебному разбирательству и принятие решения по делу. (Дополнение абзацем - Федеральный закон от 03.08.2018 № 340-ФЗ) (В редакции  Федерального закона от 05.12.2022 № 507-ФЗ)\n\n(Статья в редакции Федерального закона от 30.04.2010 № 69-ФЗ)","article_title":"Статья 152. Срок рассмотрения дела и принятия решения","amendment_eo_number":"95-ФЗ","amendment_date":"2002-07-24","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"5fef23a0285c3ae6b846ecfd669658b717798c102cf30c0f2e02fda94b27a32e"},{"code_id":"APK_RF","article_number":"153","version_date":"2002-07-24","article_text":"1. Разбирательство дела осуществляется в судебном заседании арбитражного суда с обязательным извещением лиц, участвующих в деле, о времени и месте заседания.\n\n2. Судья, а при коллегиальном рассмотрении дела председательствующий в судебном заседании:\n\n1) открывает судебное заседание и объявляет, какое дело подлежит рассмотрению;\n\n2) проверяет явку в судебное заседание лиц, участвующих в деле, их представителей и иных участников арбитражного процесса, устанавливает их личность и проверяет полномочия; устанавливает, извещены ли надлежащим образом лица, не явившиеся в судебное заседание, и какие имеются сведения о причинах их неявки;\n\n3) выясняет вопрос о возможности слушания дела;\n\n4) объявляет состав арбитражного суда, сообщает, кто ведет протокол судебного заседания, кто участвует в качестве эксперта, переводчика, и разъясняет лицам, участвующим в деле, их право заявлять отводы;\n\n5) разъясняет лицам, участвующим в деле, и иным участникам арбитражного процесса их процессуальные права и обязанности;\n\n6) удаляет из зала судебного заседания явившихся свидетелей до начала их допроса;\n\n7) предупреждает переводчика об уголовной ответственности за заведомо неправильный перевод, эксперта за дачу заведомо ложного заключения, свидетелей (непосредственно перед их допросом) за дачу заведомо ложных показаний и отказ от дачи показаний;\n\n8) определяет с учетом мнений лиц, участвующих в деле, последовательность проведения процессуальных действий и продолжительность выступлений; (В редакции Федерального закона от 28.11.2018 № 451-ФЗ)\n\n9) выясняет, поддерживает ли истец иск, признает ли иск ответчик, не хотят ли стороны закончить дело мировым соглашением или применить процедуру медиации, о чем делаются соответствующие записи в протоколе судебного заседания; (В редакции Федерального закона от 27.07.2010 № 194-ФЗ)\n\n10) руководит судебным заседанием, обеспечивает условия для всестороннего и полного исследования доказательств и обстоятельств дела, обеспечивает рассмотрение заявлений и ходатайств лиц, участвующих в деле;\n\n11) принимает меры по обеспечению в судебном заседании надлежащего порядка.","article_title":"Статья 153. Судебное заседание арбитражного суда","amendment_eo_number":"95-ФЗ","amendment_date":"2002-07-24","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"40a0e6597dd190a5c59bf854fb0ffe34ac4e6396de81c245f8392918d7cb0b2b"},{"code_id":"APK_RF","article_number":"153.1","version_date":"2002-07-24","article_text":"В случае, если лицу, участвующему в деле, иным участникам арбитражного процесса, находящимся в местах содержания под стражей или в местах отбывания лишения свободы, содействие в участии в судебном заседании путем использования систем видеоконференц-связи оказывает соответствующее учреждение, арбитражный суд, рассматривающий дело, выносит определение о проведении такого судебного заседания в соответствии со статьями 184 и 185 настоящего Кодекса. Копия определения арбитражного суда направляется в учреждение, которое обеспечивает проведение судебного заседания путем использования систем видеоконференц-связи в соответствии со статьей 1551 Гражданского процессуального кодекса Российской Федерации. (Дополнение абзацем - Федеральный закон от 25.12.2023 № 667-ФЗ)\n\n(Дополнение частью - Федеральный закон от 01.05.2016 № 137-ФЗ)\n\n1) отсутствует техническая возможность для участия в судебном заседании с использованием систем видеоконференц-связи;\n\n2) разбирательство дела осуществляется в закрытом судебном заседании.\n\n(Дополнение статьей - Федеральный закон от 27.07.2010 № 228-ФЗ)","article_title":"Статья 153.1. Участие в судебном заседании путем использования систем видеоконференц-связи","amendment_eo_number":"95-ФЗ","amendment_date":"2002-07-24","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"fe891764684949b24afc64b80aaf236e671e5e7b538ae7ebee5d99d856503231"},{"code_id":"APK_RF","article_number":"153.2","version_date":"2002-07-24","article_text":"1. Лица, участвующие в деле, и иные участники арбитражного процесса могут участвовать в судебном заседании путем использования системы веб-конференции при условии заявления ими соответствующего ходатайства и при наличии в арбитражном суде технической возможности осуществления веб-конференции.\n\nУстановление личности гражданина, его представителя или представителя юридического лица, участвующих в судебном заседании путем использования системы веб-конференции, осуществляется с использованием информационно-технологических средств, обеспечивающих идентификацию лица без его личного присутствия (единой системы идентификации и аутентификации, единой биометрической системы).\n\nАрбитражный суд в электронном виде заблаговременно направляет лицам, участвующим в деле, информацию, необходимую для участия в судебном заседании путем использования системы веб-конференции. При отказе в удовлетворении ходатайства об участии в судебном заседании путем использования системы веб-конференции арбитражный суд в электронном виде направляет лицам, участвующим в деле, информацию о таком отказе с указанием его оснований. (В редакции  Федерального закона от 25.12.2023 № 667-ФЗ)\n\nАбзац. (Утратил силу - Федеральный закон от 25.12.2023 № 667-ФЗ)\n\n2. Арбитражный суд, рассматривающий дело, отказывает в удовлетворении ходатайства об участии в судебном заседании путем использования системы веб-конференции в случае, если:\n\n1) отсутствует техническая возможность для участия в судебном заседании с использованием системы веб-конференции;\n\n2) разбирательство дела осуществляется в закрытом судебном заседании.\n\n3. Лица, участвующие в деле, и иные участники арбитражного процесса, участвующие в судебном заседании путем использования системы веб-конференции, вправе в ходе судебного заседания подавать в арбитражный суд заявления, ходатайства и прилагаемые к ним документы в электронном виде.\n\n4. Арбитражный суд, рассматривающий дело, берет подписку у свидетелей, экспертов, переводчиков, участвующих в судебном заседании путем использования системы веб-конференции, о разъяснении им прав и обязанностей и предупреждении об ответственности за их нарушение, которая представляется в арбитражный суд в форме электронного документа, подписанного усиленной квалифицированной электронной подписью.\n\n5. При использ\n\nовании системы веб-конференции составляется протокол и ведется видеозапись судебного заседания. Материальный носитель видеозаписи судебного заседания приобщается к протоколу судебного заседания.\n\n(Дополнение статьей - Федеральный закон от 30.12.2021 № 440-ФЗ)","article_title":"Статья 153.2. Участие в судебном заседании путем использования системы веб-конференции","amendment_eo_number":"95-ФЗ","amendment_date":"2002-07-24","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"29b4b9f6c2f1150fae3aa3855ea45b9023f943958e7041c077f920a15dc0eb33"},{"code_id":"APK_RF","article_number":"154","version_date":"2002-07-24","article_text":"1. При входе судей в зал судебного заседания все присутствующие в зале встают. Решение арбитражного суда все находящиеся в зале судебного заседания лица выслушивают стоя.\n\n2. Лица, участвующие в деле, и иные участники арбитражного процесса обращаются к арбитражному суду со словами: \"Уважаемый суд!\" Свои объяснения и показания суду, вопросы другим лицам, участвующим в деле, ответы на вопросы они дают стоя. Отступление от этого правила может быть допущено только с разрешения суда.","article_title":"Статья 154. Порядок в судебном заседании","amendment_eo_number":"95-ФЗ","amendment_date":"2002-07-24","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"2f5d05ecda0d7ed05c7b1efd033fc31479f5d744855b80fef59edb08ba7ea992"},{"code_id":"APK_RF","article_number":"155","version_date":"2002-07-24","article_text":"1. В ходе каждого судебного заседания арбитражного суда первой инстанции, а также при совершении отдельных процессуальных действий вне судебного заседания ведется протоколирование с использованием средств аудиозаписи и составляется протокол в письменной форме (далее также - протокол).\n\n2. Протокол является дополнительным средством фиксирования следующих данных о ходе судебного заседания:\n\n1) год, месяц, число и место проведения судебного заседания;\n\n2) время начала и окончания судебного заседания;\n\n3) наименование арбитражного суда, рассматривающего дело, состав суда;\n\n4) наименование и номер дела;\n\n5) сведения о предупреждении об уголовной ответственности переводчика за заведомо неправильный перевод, свидетелей за дачу заведомо ложных показаний и отказ от дачи показаний, эксперта за дачу заведомо ложного заключения;\n\n6) устные заявления и ходатайства лиц, участвующих в деле, консультации специалистов; (В редакции Федерального закона от 08.12.2011 № 422-ФЗ)\n\n7) соглашения сторон по фактическим обстоятельствам дела и заявленным требованиям и возражениям;\n\n8) определения, вынесенные судом без удаления из зала судебного заседания;\n\n9) отметка об использовании средств аудиозаписи, систем видеоконференц-связи либо системы веб-конференции и (или) иных технических средств, о проведении кино- и фотосъемки, видеозаписи, трансляции судебного заседания по радио, телевидению и в информационно-телекоммуникационной сети \"Интернет\" в ходе судебного заседания. При проведении трансляции судебного заседания указывается также наименование средства массовой информации или сайта в информационно-телекоммуникационной сети \"Интернет\", посредством которых осуществлялась трансляция; (В редакции федеральных законов от 29.07.2017 № 223-ФЗ, от 30.12.2021 № 440-ФЗ)\n\n10) дата составления протокола.\n\n3. В протоколе о совершении отдельного процессуального действия указываются также сведения, полученные в результате совершения этого процессуального действия.\n\n4. Секретарь судебного заседания или помощник судьи составляет протокол и обеспечивает использование средств аудиозаписи и (или) иных технических средств в ходе судебного заседания.\n\n5. Протокол может быть написан от руки или составлен с использованием технических средств. Протокол подписывается председательствующим в судебном заседании, секретарем судебного заседания или помощником судьи, который составлял протокол судебного заседания, не позднее следующего дня после дня окончания судебного заседания, а протокол о совершении отдельного процессуального действия - непосредственно после совершения отдельного процессуального действия.\n\n6. Протоколирование судебного заседания с использованием средств аудиозаписи ведется непрерывно в ходе судебного заседания. Материальный носитель аудиозаписи приобщается к протоколу.\n\nВ случае, если арбитражным судом проводится стенографическая запись, а также видеозапись судебного заседания, в протоколе, составленном в письменной форме, должны быть указаны сведения, предусмотренные пунктами 5, 6, 8 и 9 части 2 настоящей статьи. Материальный носитель видеозаписи приобщается к протоколу.\n\nЗамечания на протокол, представленные в арбитражный суд по истечении пятидневного срока, судом не рассматриваются и возвращаются лицу, представившему эти замечания. (В редакции Федерального закона от 28.11.2018 № 451-ФЗ)\n\n(Статья в редакции Федерального закона от 27.07.2010 № 228-ФЗ)","article_title":"Статья 155. Протокол","amendment_eo_number":"95-ФЗ","amendment_date":"2002-07-24","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"0c6e6e9862985d127a332f48f8eb80dc806a51b5bb4fa39a4f9b5ff17a800345"},{"code_id":"APK_RF","article_number":"156","version_date":"2002-07-24","article_text":"1. Непредставление отзыва на исковое заявление или дополнительных доказательств, которые арбитражный суд предложил представить лицам, участвующим в деле, не является препятствием к рассмотрению дела по имеющимся в деле доказательствам.\n\n2. Стороны вправе известить арбитражный суд о возможности рассмотрения дела в их отсутствие.\n\n3. При неявке в судебное заседание арбитражного суда истца и (или) ответчика, надлежащим образом извещенных о времени и месте судебного разбирательства, суд вправе рассмотреть дело в их отсутствие.\n\n4. В случае, если в судебное заседание не явились лица, участвующие в деле, а их явка в соответствии с настоящим Кодексом была признана обязательной арбитражным судом, суд может наложить на указанных лиц судебный штраф в порядке и в размерах, которые предусмотрены в главе 11 настоящего Кодекса.\n\n5. При неявке в судебное заседание иных лиц, участвующих в деле и надлежащим образом извещенных о времени и месте судебного разбирательства, суд рассматривает дело в их отсутствие.","article_title":"Статья 156. Рассмотрение дела при непредставлении отзыва на исковое заявление, дополнительных доказательств, а также в отсутствие лиц, участвующих в деле","amendment_eo_number":"95-ФЗ","amendment_date":"2002-07-24","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"46df8776d28fcdbf56af022e3a4c6cb097a3c4efca2fe07b0ff93a14f784c35a"},{"code_id":"APK_RF","article_number":"157","version_date":"2002-07-24","article_text":"1. При неявке в судебное заседание экспертов, свидетелей, переводчиков, надлежащим образом извещенных о времени и месте судебного заседания, арбитражный суд выносит определение об отложении судебного разбирательства, если стороны не заявили ходатайство о рассмотрении дела в отсутствие указанных лиц.\n\n2. В случае, если вызванные в судебное заседание эксперт, свидетель, переводчик не явились в суд по причинам, признанным судом неуважительными, суд может наложить на них судебный штраф в порядке и в размере, которые установлены в главе 11 настоящего Кодекса.","article_title":"Статья 157. Последствия неявки в судебное заседание экспертов, свидетелей, переводчиков","amendment_eo_number":"95-ФЗ","amendment_date":"2002-07-24","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"d8d400f1dde59d38443fa39ff5f8f29cdc24c5d0115ed49e59c7e787a3777b85"},{"code_id":"APK_RF","article_number":"158","version_date":"2002-07-24","article_text":"1. Арбитражный суд откладывает судебное разбирательство в случаях, предусмотренных настоящим Кодексом, а также в случае неявки в судебное заседание лица, участвующего в деле, если в отношении этого лица у суда отсутствуют сведения об извещении его о времени и месте судебного разбирательства.\n\nСудебное разбирательство также может быть отложено по решению председателя арбитражного суда, заместителя председателя арбитражного суда или председателя судебного состава в случае болезни судьи или по иным причинам невозможности проведения судебного заседания на срок, не превышающий одного месяца. (Дополнение абзацем - Федеральный закон от 27.07.2010 № 228-ФЗ) (В редакции  Федерального закона от 25.12.2023 № 667-ФЗ)\n\n10. Судебное разбирательство в новом судебном заседании возобновляется с того момента, с которого оно было отложено. Повторное рассмотрение доказательств, исследованных до отложения судебного разбирательства, не производится.","article_title":"Статья 158. Отложение судебного разбирательства","amendment_eo_number":"95-ФЗ","amendment_date":"2002-07-24","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"76dfdec1b4fb46344dd1c16cf7f019876246e193ec0a28d1d3dfb27134239244"},{"code_id":"APK_RF","article_number":"16","version_date":"2002-07-24","article_text":"1. Вступившие в законную силу судебные акты арбитражного суда являются обязательными для органов государственной власти, органов местного самоуправления, иных органов, организаций, должностных лиц и граждан и подлежат исполнению на всей территории Российской Федерации.\n\nТребования арбитражного суда о представлении доказательств, сведений и других материалов, даче объяснений, разъяснений, заключений и иные требования, связанные с рассматриваемым делом, являются также обязательными и подлежат исполнению органами, организациями и лицами, которым они адресованы.\n\n11. Специализированный арбитражный суд в целях получения разъяснений, консультаций и выяснения профессионального мнения ученых, специалистов и прочих лиц, обладающих теоретическими и практическими познаниями по существу разрешаемого специализированным арбитражным судом спора, может также направлять запросы.\n\nЗапросы о даче разъяснений, консультаций и об изложении профессиональных мнений по рассматриваемым специализированным арбитражным судом делам обязательны для всех органов, организаций и лиц, которым они адресованы.\n\nЗапросы должны быть рассмотрены и ответ по результатам их рассмотрения должен быть направлен в специализированный арбитражный суд в течение месяца со дня получения этих запросов, если иной срок не указан специализированным арбитражным судом.\n\n(Дополнение частью - Федеральный закон от 08.12.2011 № 422-ФЗ)\n\n2. Неисполнение судебных актов, а также невыполнение требований арбитражных судов влечет за собой ответственность, установленную настоящим Кодексом и другими федеральными законами.\n\n3. Обязательность судебных актов не лишает лиц, не участвовавших в деле, возможности обратиться в арбитражный суд за защитой нарушенных этими актами их прав и законных интересов путем обжалования указанных актов.\n\n4. Признание и обязательность исполнения на территории Российской Федерации судебных актов, принятых иностранными судами, иностранных арбитражных решений определяются международным договором Российской Федерации, федеральным законом.","article_title":"Статья 16. Обязательность судебных актов","amendment_eo_number":"95-ФЗ","amendment_date":"2002-07-24","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"cee55c5c6421b2e0f130feb218c533fc67f6afcc1a9f722830bf7a87d5248fb4"},{"code_id":"APK_RF","article_number":"160","version_date":"2002-07-24","article_text":"1. В случае, если в одном заявлении соединены требование об установлении оснований ответственности ответчика и связанное с ним требование о применении мер ответственности, арбитражный суд вправе с согласия сторон рассмотреть такие требования в раздельных судебных заседаниях.\n\nО рассмотрении дела в раздельных судебных заседаниях выносится определение.\n\n2. При отказе в удовлетворении требования об установлении оснований ответственности ответчика арбитражный суд не рассматривает связанное с ним требование о применении мер ответственности и второе судебное заседание не проводит.\n\n3. В случае удовлетворения требования об установлении оснований ответственности ответчика арбитражный суд сразу же или после перерыва, срок которого не может превышать пять дней, вправе провести второе судебное заседание и в этом судебном заседании рассмотреть требование о применении мер ответственности, в том числе определить размер взыскиваемой суммы. По результатам рассмотрения арбитражный суд принимает решение по всем заявленным требованиям.\n\n4. В случае, если в судебном заседании объявлялся перерыв, во время которого стороны достигли договоренности или урегулировали спор в части требований о применении мер ответственности, арбитражный суд не рассматривает эти требования и прекращает производство по делу в части требований о применении мер ответственности при условии, что истец обратился с отказом в письменной форме от иска или стороны заключили мировое соглашение в этой части требований и отказ принят либо мировое соглашение утверждено судом, на что указывается в судебном акте арбитражного суда.","article_title":"Статья 160. Рассмотрение дела в раздельных заседаниях арбитражного суда","amendment_eo_number":"95-ФЗ","amendment_date":"2002-07-24","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"6bb0c5926f132a9f17b3b60e3792ec3d39ff6a423f8e0d23716dc563be2eb7b6"},{"code_id":"APK_RF","article_number":"161","version_date":"2002-07-24","article_text":"1. Если лицо, участвующее в деле, обратится в арбитражный суд с заявлением в письменной форме о фальсификации доказательства, представленного другим лицом, участвующим в деле, суд:\n\n1) разъясняет уголовно-правовые последствия такого заявления;\n\n2) исключает оспариваемое доказательство с согласия лица, его представившего, из числа доказательств по делу;\n\n3) проверяет обоснованность заявления о фальсификации доказательства, если лицо, представившее это доказательство, заявило возражения относительно его исключения из числа доказательств по делу.\n\nВ этом случае арбитражный суд принимает предусмотренные федеральным законом меры для проверки достоверности заявления о фальсификации доказательства, в том числе назначает экспертизу, истребует другие доказательства или принимает иные меры.\n\n2. Результаты рассмотрения заявления о фальсификации доказательства арбитражный суд отражает в протоколе судебного заседания.","article_title":"Статья 161. Заявление о фальсификации доказательства","amendment_eo_number":"95-ФЗ","amendment_date":"2002-07-24","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"c4e17eccc811950c52c43a5697ba492a123f0d37db03582f94c168cbc9792d6c"},{"code_id":"APK_RF","article_number":"163","version_date":"2002-07-24","article_text":"1. Арбитражный суд по ходатайству лица, участвующего в деле, или по своей инициативе может объявить перерыв в судебном заседании.\n\n2. Перерыв в судебном заседании может быть объявлен на срок, не превышающий десяти дней. (В редакции  Федерального закона\n\n3. На перерыв в пределах дня судебного заседания и время, когда заседание будет продолжено, указывается в протоколе судебного заседания.\n\nО перерыве на более длительный срок арбитражный суд выносит определение, которое заносится в протокол судебного заседания. В определении указываются время и место продолжения судебного заседания.\n\n4. После окончания перерыва судебное заседание продолжается, о чем объявляет председательствующий в судебном заседании. Повторное рассмотрение исследованных до перерыва доказательств не производится, в том числе при замене представителей лиц, участвующих в деле.\n\n5. Лица, участвующие в деле и присутствовавшие в зале судебного заседания до объявления перерыва, считаются надлежащим образом извещенными о времени и месте судебного заседания, и их неявка в судебное заседание после окончания перерыва не является препятствием для его продолжения.","article_title":"Статья 163. Перерыв в судебном заседании","amendment_eo_number":"95-ФЗ","amendment_date":"2002-07-24","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"a5105f88c84d06170ea127a0c947e4202a30519d3713b06efd2fbb1787591b1a"},{"code_id":"APK_RF","article_number":"164","version_date":"2002-07-24","article_text":"1. После завершения исследования всех доказательств председательствующий в судебном заседании выясняет у лиц, участвующих в деле, не желают ли они чем-либо дополнить материалы дела. При отсутствии таких заявлений председательствующий в судебном заседании объявляет исследование доказательств законченным и суд переходит к судебным прениям.\n\n2. Судебные прения состоят из устных выступлений лиц, участвующих в деле, и их представителей. В этих выступлениях они обосновывают свою позицию по делу.\n\n3. В судебных прениях первыми выступают истец и (или) его представитель, затем - третье лицо, заявляющее самостоятельные требования относительно предмета спора, ответчик и (или) его представитель. Третье лицо, не заявляющее самостоятельных требований относительно предмета спора, выступает после истца или после ответчика, на стороне которого оно участвует в деле.\n\nПрокурор, представитель государственного органа, органа местного самоуправления и иного органа, обратившиеся в арбитражный суд в соответствии со статьями 52 и 53 настоящего Кодекса, выступают в судебных прениях первыми.\n\n4. Участники судебных прений не вправе ссылаться на обстоятельства, которые судом не выяснялись, и на доказательства, которые не исследовались в судебном заседании или признаны судом недопустимыми.\n\n5. После выступления всех участников судебных прений каждый из них вправе выступить с репликами. Право последней реплики всегда принадлежит ответчику и (или) его представителю.","article_title":"Статья 164. Судебные прения","amendment_eo_number":"95-ФЗ","amendment_date":"2002-07-24","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"1de894768f93f93cc7a138c2afcb60cb3c286bbeeb2259325b19e9d6a3b70c84"}]$law7d0004$::jsonb) as x(code_id text,article_number text,version_date date,article_text text,article_title text,amendment_eo_number text,amendment_date date,is_current boolean,is_repealed boolean,repealed_date date,text_hash text))
insert into law7_mirror.article_versions(code_id,article_number,version_date,article_text,article_title,amendment_eo_number,amendment_date,is_current,is_repealed,repealed_date,text_hash,source_commit,imported_at)
